type Role = "client" | "lawyer" | "admin";
type Session = { token:string; user:{id:number;role:Role;name:string;avatarUrl?:string} };
type Route = {name:string; id?:number; slug?:string; specialtyId?:number};
type IntakeKind = "question"|"text"|"phone"|"in_person";
type ConsultMode = "text"|"phone"|"in_person";
type IntakeDraft = {step:number;topic:string;body:string;kind:IntakeKind;publish:boolean;urgent:boolean;lawyerId?:number|null;file?:File|null};
