 const firstOffset=(cursor.getDay()+1)%7,daysInMonth=new Date(cursor.getFullYear(),cursor.getMonth()+1,0).getDate();
 const normalized=(Array.isArray(items)?items:[]).map((item:any)=>({...item,eventAt:item.starts_at||item.start_at||item.scheduled_at||""})).filter((item:any)=>item.eventAt);
